import React from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { FaHome, FaCheckCircle, FaComments, FaClock, FaUserCircle, FaSignOutAlt, FaBrain } from 'react-icons/fa';

function Navbar() {
  const navigate = useNavigate();
  const location = useLocation();

  const navItems = [
    { path: '/dashboard', icon: <FaHome />, label: 'Home' },
    { path: '/habits', icon: <FaCheckCircle />, label: 'Habits' },
    { path: '/chat', icon: <FaComments />, label: 'AI Chat' },
    { path: '/timer', icon: <FaClock />, label: 'Timer' },
    { path: '/profile', icon: <FaUserCircle />, label: 'Profile' },
  ];

  const handleLogout = () => {
    localStorage.removeItem('isLoggedIn');
    localStorage.removeItem('userName');
    navigate('/');
  };

  return (
    <div style={styles.navbar}>
      <div style={styles.navContent}>
        <div style={styles.logo} onClick={() => navigate('/dashboard')}>
          <FaBrain size={28} color="#667eea" />
          <span style={styles.logoText}>Mind<span style={{ color: '#764ba2' }}>Ease</span></span>
        </div>
        
        <div style={styles.navLinks}>
          {navItems.map((item) => (
            <div
              key={item.path}
              style={{
                ...styles.navItem,
                ...(location.pathname === item.path ? styles.navItemActive : {})
              }}
              onClick={() => navigate(item.path)}
            >
              {item.icon}
              <span style={styles.navLabel}>{item.label}</span>
            </div>
          ))}
          <div style={styles.navItem} onClick={handleLogout}>
            <FaSignOutAlt />
            <span style={styles.navLabel}>Logout</span>
          </div>
        </div>
      </div>
    </div>
  );
}

const styles = {
  navbar: {
    position: 'fixed',
    top: 0,
    left: 0,
    right: 0,
    background: 'white',
    boxShadow: '0 2px 20px rgba(0,0,0,0.1)',
    zIndex: 1000,
  },
  navContent: {
    maxWidth: '1200px',
    margin: '0 auto',
    padding: '15px 20px',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    flexWrap: 'wrap',
  },
  logo: {
    display: 'flex',
    alignItems: 'center',
    gap: '10px',
    cursor: 'pointer',
  },
  logoText: {
    fontSize: '24px',
    fontWeight: 'bold',
    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
    WebkitBackgroundClip: 'text',
    WebkitTextFillColor: 'transparent',
  },
  navLinks: {
    display: 'flex',
    gap: '20px',
    flexWrap: 'wrap',
  },
  navItem: {
    display: 'flex',
    alignItems: 'center',
    gap: '8px',
    padding: '8px 16px',
    borderRadius: '50px',
    cursor: 'pointer',
    transition: 'all 0.3s ease',
    color: '#666',
  },
  navItemActive: {
    background: 'linear-gradient(135deg, #667eea20 0%, #764ba220 100%)',
    color: '#667eea',
  },
  navLabel: {
    fontSize: '14px',
    fontWeight: '500',
  },
};

export default Navbar;
